import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷九","description":"周易經傳集解 - 周易經傳集解卷九","frontmatter":{"title":"周易經傳集解卷九","description":"周易經傳集解 - 周易經傳集解卷九"},"headers":[],"relativePath":"classics/jingchuan-jijie/010.md","filePath":"classics/jingchuan-jijie/010.md"}'),r={name:"classics/jingchuan-jijie/010.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷九",tabindex:"-1"},[n("周易經傳集解卷九 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷九","aria-label":"Permalink to “周易經傳集解卷九”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解隨蠱卷九 ​宋林栗撰。序卦曰：「豫必有隨，故受之以隨。」「隨」之成卦，「豫」之變也。自「豫」之「隨」，震來居下，「坤」變為「兌」，相易而成也。震耒居下，動乎「坤」也。坤變為「兌」，說乎「震」也。剛來下柔，則柔隨之，動而說，所以為隨也。夫豫之為言，安逸而怠惰者也。安逸而怠惰，不能復振，則死期至矣。豫而不死，其必有所隨乎？昧爽而興，何悔怠，是之謂「隨」也矣。是故自「豫」之「隨」，上變六五，下變初六，而隨之象可見矣。變初為九，則「鳴豫」之㓙，為「有渝」之「吉」。變五為九，則乘剛之疾，為「嘉吉」之孚。以「豫」之上體，為隨之下體，上居震之終，下居震之始，故上六「成有渝，無咎」，而初九「官有渝，貞吉」，蓋相因之辭也。學者顧以剛來下柔為豫之變，不已疏乎？隨：元亨利貞，無咎。彖曰：「隨」，剛來而下柔，動而說，隨。大亨貞，無咎，而天下隨時。隨時之義大矣哉！下震上兌，成卦曰「隨」者，初為震，二為艮，三為巽，四為兌。震為春，巽為夏，兌為秋，艮為冬，四時之義備矣。震為元，巽為亨，兌為利，艮為貞，四德之行成矣。夫人者，隨天者也。臣者，隨君者也。天有四時，人之所隨也。君有四德，臣之所隨也。故曰：「隨，元亨利貞，無咎。」四時不傋，則寒暑失序，人不可以隨天。四德不具，則威福旡章，下不可以隨上。「元亨利貞」四者無咎，而後天下隨之矣。孟子曰：「身不行道，不行於妻子。」其是之謂乎？子曰：隨，剛來而下柔，動而說，隨。大亨貞，無咎，而天下隨時。隨時之義大矣哉！「剛來」下柔，「震」下「兌」上也。「動而說」，亦「震」「兌」也。九五者，「隨」之主也。初九者，隨之言也。惟其下之，是以上之也。「隨之」二字重複，故傳寫訛誤。朱氏曰：「王肅本作隨之，今定讀雲。大亨貞無咎，而天下隨之。隨之時義大矣哉！」彖稱四德，而夫子但言「大亨貞」，何也？「元」盡乎「大」，而利兼乎「亨」也。「隨」之時義，於斯為大矣。其詳已見屯彖。魯穆姜之筮也，曰：「有四德者，隨而無咎，我皆無之，豈隨也哉？」嗚呼！穆姜其知道矣，而不能制淫慝之心，以陷於大惡，惜乎其悔之晚也。象曰：澤中有雷，「隨」。君子以嚮晦入宴息。「澤」者，「兌」也。「雷」者，「震」也。澤中有雷，澤之所「隨」也。雷上於天，則澤氣隨之而升。雷下於澤，則澤氣隨之而降。耿氏曰：「雷之發聲以仲春，仲春，震也。其收聲以仲秋，仲秋，兌也。」雷出地奮，乃發聲於震之時，故為豫。澤中有雷，乃收聲於兌之時，故為隨。震以動出為材，故震為雷。然之收聲於兌，以隨時而已。是故君子體之，以嚮晦入宴息。日出而明，君子隨之而作；日入而晦，君子隨之而息。隨之時義也。震為日出，兌為日入故也。傳曰：「君子有四時：朝以聽政，晝以訪問，夕以修令，夜以安身。」此之謂也。系曰：「服牛乘馬，引重致遠，以利天下，蓋取諸隨。」何也？曰：澤者隨雷者也，雷者隨時者也；人者隨天者也，牛馬隨人者也，臣隨君者也，妻隨夫者也，學者隨師者也。自雖聖人，未有能幹時而動者，隨之時義，顧不大哉？雜卦曰：「隨，無故也。」隨之為卦，以兌隨震而成。其在六爻，以所隨為義。書曰：「德無常師，主善為師；善無常主，恊於克一。」是以隨之時義，不主於故常，惟其可以隨則隨之也。夫陽者，陰之所隨也；上者，下之所隨也。然初九之隨六二，則以下爻隨上爻，而非陰之隨陽也。上六之隨九五，則以陰爻隨陽爻，而非下之隨上也。是之謂「無故也」。夫隨也者，當位而相應則隨之也，六二之隨九五是已。然六三之隨九四，則以近而相與，非當位而相應也。夫「隨」也者，一陰而一陽則隨之也。兩剛不能以相事，兩柔不能以相使，則無相隨之義也，六二之於六三是已。然九四之於九五，則兩爻皆剛而有相隨之義，何也？是之謂無故也。夫無故者，必有其故也。王之所在，陽不可以不隨於陰；弟之所反，上不可以不隨於下。有之於上，雖近而不害於隨；有位於中，雖均而不敢隨也。隨之無故，不其然乎？是故九五居中履正，孚於二四。初九，隨二者也；六三，隨四者也，固已旡思不服矣。至於上六處卦之終，居五之上，雖欲勿隨，不可得也。此象所謂「大亨貞無咎」，而天下隨之者也。初九：官有渝，貞吉。出門交有功。象曰：「官有渝」，從正吉也；「出門交有功」，不失也。初九，「震」也。以陽居剛而在下卦之下，上無其應，而「隨」六二之「艮」，故曰：「官有渝，貞吉，出門交有功。」「官」者，主宰之謂也。所以為「隨」者，「震」也。所以為「震」者，初九也。故有「官」之象焉。「官」也者，人之所隨，而非隨人者也。然堯舜禹湯不能旡過，苟固執而不變，寧咈百姓以從己，不肯捨己以從人，亡之道也。孔子有言：「如其善而莫之違也，不亦善乎？如不善而莫之違也，不幾乎一言而喪邦乎？」「渝」者，變也。變而從正，則「吉」也。故曰：「貞吉」。從善如流，改過不吝，以此為「貞」，宜其「吉」矣。然為物之主，而惟人是隨。所隨不正，則陷於邪僻矣；所隨不廣，則陷於私暱矣。故曰：「出門交有功。」初九為「震」，「震」為出；六二為「艮」，「艮」為門闕，故有「出門」之象焉。以六居二，則所隨者正矣。出門遇二，遂與之交，則所隨者廣矣。所隨者正，則不悖於道；所隨者廣，則不失於人。吉且「有功」，不亦宜乎？故子曰：官有渝，從正吉也。「出門交有功，不失也。」六二在「豫」說為中正矣，初六陰柔，不能從正，以成「鳴豫」之兇，至於是而從之，斯能變兇為吉也。或曰：子以震為出，艮為門闕，則「同人」初、二以離遇巽，亦有出門之象，何哉？曰：由「艮」而出乎「震」，由「巽」而相見乎「離」，「艮」、「震」皆陽，「離」、「巽」皆陰，其為出門之遇一也。然「同人」之門，取諸全象之則；而「隨」之門，取諸「艮」、「震」之交，蓋不一而足矣。六二：系小子，失丈夫。象曰：「系小子」，弗兼與也。六二，「艮」也。以陰居柔，而在下卦之中，應乎九五之「兌」，上隨六三，而下為初九之所隨者也。故曰：「系小子，失丈夫」。初為「震」，「震」為長男，故有「丈夫」之象。三有「艮」體，二之於三，三之於四，四之於五，皆「艮」，「艮」為少男，故有「小子」之象。「系」，牽也。初之於二，勢之所牽也。然初之於二，四之於五，其所隨者正，而非以其勢隨之也，是以不謂之系也。若六三、九四不得其正，而有隨之者，豈非其所繫之故歟？夫君子之所為隨者，謂理義之所在，而人心之所同然者也。苟為其所繫而隨之，有所繫則有所失矣。系邪而失正，君子不為也；系小而失大，君子不為也。六二在「豫」，所謂「上交不謟，下交不瀆」者。及其在隨，所繫者六三而已。三以陰柔不當其位，豈君子之所宜隨哉？繫於三，則失於初矣。初九，正也；六三不正也。初震丈夫也；三艮小子也。夫初之所以隨二者，以二之中正，故舍己而從之也。一系於三，則喪其正矣，其失於初九，宜哉！夫以六二上應九五，下交初九，無不得其正矣。其於六三，雖有所繫，必不肯枉道以從之也。然二爻皆柔，同體乎「艮」，故為之戒云爾。子曰：「系小子，弗兼與也。」使其繫於小子而不失於丈夫，狥於一人之慾而不咈天下之情，則何惡於詭隨也哉！惟其邪正小大弗可以兼與，是以君子見幾而作也。六三：系大夫，失小子。隨有求得，利居貞。象曰：「系丈夫」，志舍下也。六三下體為「艮」，上體為「巽」，以陰居剛而在下卦之上，上無其應而隨於九四，故曰：「系丈夫，失小子」。二為「艮」，「艮」為「小子」。四有震體，「震」為「丈夫」。三繫於四，則失於二矣。三之系四而失二，與二之系三而失初，一也。然而三可以繫於四，二不可以繫於三，何也？曰：三，「艮」也，而四則「兌」也。三，「巽」也，而四則「震」也。三，六也，而四則九也。居上下之交，在人倫之位，相與以成，相須以立者也。系而隨之，不亦可乎？方隨之時，九五在天，上下之所共隨也。三遠於五，不繫於四，無以達焉。二自配五，反繫於三，失之遠矣。丈夫者，人之所隨也；「小子」者，隨人者也。是以系失同而否臧異也。或曰：二中正而謂之「小子」，何也？曰：君子小人，何常之有？立其大則為大人，狥其小則為小人。使二不能自立而惟三之隨，其謂之小子也宜哉！故曰「隨有求得」。以「艮」而求「兌」，則得之矣；以「巽」而求「震」，則得之矣；以六而求九，則得之矣；以三而求四，則得之矣；此其所以隨之也。然志在隨人，有求則得，將無所不至矣，故曰「利居貞」。三止而「巽」，其能居貞矣哉！故子曰「系丈夫，志舍下也」。「舍」，上聲讀。「下」謂二也。九四：隨有獲，貞㓙有孚，在道以明，何咎？象曰：「隨有獲」，其義兇也。「有孚在道」，明功也。九四上體為「兌」，下體為「震」，以陽居柔，而在上卦之下，下無其應，而上隨九五，下為六三之所隨也，故曰「隨有獲」，隨人而有獲也。「隨」之九四，即「豫」之九四也。在「豫」為「有得」，在「隨」為「有獲」。隨者，五也；「獲」者三也。隨五而獲，三五之所不能，旡疑也。隨人而不免於疑，失其道矣。獲人之財，猶謂之盜，況獲君之民乎？故曰「貞㓙」。以此為「貞」，「兇」其宜也。戰國之際，齊有孟嘗，趙有平原，楚有春申，魏有信陵。此四公子尊賢而下士，天下之有材智者，不遠千里而歸之。當是之時，列國相傾，以士為重。然其時君猶不能堪。至於漢興，相國蕭何為民請苑，以高皇之大度，猶不免械擊之辱。其後魏其、武安，招致賓客，人主切齒，卒以誅滅。故衛將軍以為招賢選士，人主之柄，人臣何得招士？懲此祻也。古之人如伊尹、周公，以身任天下之重，受天下之歸，而無所顧忌於其間，其必有道矣。故曰：「有孚在道，以明何咎？」惟其憂國之誠心，澤民之素志，有以取信於上。上之人知其志在於行道，而非有背公營私、附下罔上之趣也，非有招權固位、欺君盜國之謀也。苟有以自明，何咎之有？昔者伊尹在畎畝之中，幡然而起曰：「吾豈若使是君為堯舜之君，使是民為堯舜之民？天之生是人也，使先知覺後知，先覺覺後覺。予將以斯道覺斯民也。」周公勤勞王家，卑躬下士，一飯三吐哺，一沐三握髮，惟恐失天下之賢人，親執贄而見者千人，還贄而相見者三千人，貌執之士百有餘人，欲言而請畢事者千有餘人。二公之行不同，其有獲於斯民一也。而湯武在上，未嘗置纖芥之疑，豈非「有孚在道，其志自明」也哉？故子曰：隨有獲，其義兇也。有孚在道，明功也。五不孚四，旡以獲三，四之於五，可謂有功矣。有孚於上則為功，無以自明則為賊。處斯地者，可不鑑茲哉？曰：豫之有得，隨之有獲，其義一也。一則為大，一則為㓙，何也？曰：非其有而得之謂之獲。豫之所承者，六五也。五非四無以得民，是以為大也。隨之所承者，九五也。五居正中，而四獲於下，是以為㓙也。九五：孚於嘉，吉。象曰：「孚於嘉，吉」，位正中也。九五，「兌」也，以陽居剛，而在上卦之中，應乎六二之「艮」，而為上下之所隨者也。故曰：「孚於嘉吉。」「嘉」，猶配也。昏禮謂之「嘉」，傳曰「嘉偶」，曰「妃子」，曰嘉會，足以合禮是也。不曰「配」而曰「嘉」者，「嘉」之言美也，賢人君子之謂也。九五之所謂「嘉」者，其六二之謂乎？二為「艮」，五為「兌」，有感應相與之象焉，夫是以謂之「嘉」也。二五交孚，人莫能間，君臣之義，夫婦之道，於是為至矣。天下以平，家國以治，謂之「吉」也，不亦宜乎？或曰：二於五為嘉，而下交於初九，何也？曰：初九者，五之未得其位，而來下於柔者也。卦以「隨」為義，初隨二者也，非二之隨初也。其於初也，為出門之交；其於五也，為「嘉偶」之「孚」矣。五位乎天，剛柔上下，莫不隨之，然後六二之「嘉」始合也。故子曰：「孚於嘉吉，位正中也。」或曰：五雖中正，何以見剛柔上下莫不隨之？曰：二，五之配也；四，五之鄰也。其隨之也，不佔而決以六三、初九，遠非其配，近非其鄰，三繫於四，初交於二，是以隨之也。二四則有功於五矣。故初曰「有功」，四曰「明功」，互發其文也。若上六窮而無歸，舍五何適哉？或曰：子以初九為九五下柔之象，又曰初交於二，所以隨五也。義孰從乎？曰：「自豫」之「隨」，其變者初與五也。九五來中，而初九在下，是以為剛來下柔也。及其正中矣，則初九者豈非因二以隨五者乎？是謂「大亨貞無咎」，而天下隨之也。上六：拘繫之，乃從維之。王用享於西山。象曰：「拘繫之」，上窮也。上六，「巽」也。以陰居柔，而在上卦之上，下無其應，而隨於九五之「兌」，故曰：「拘繫之，乃從維之。」「巽」為繩，故有系維之象。柔之為物，不能獨立，必有所繫。在卦二陰，惟三上有「巽」體，故三繫於四，上繫於五。至於六二，雖承六三，而不體乎「巽」，是以系而不繫也。夫隨也者，自下隨上也。今上六以陰柔之資，而居九五之上，本非隨五，而又非五之所隨也。然而居一卦之上，上無所隨，下無所應，而五位中正，天下隨之，上六雖欲勿隨，不可得矣。五之於上也，其來不拒，其去不追，非有必於其隨也。上六窮而無歸，其勢必將挽九五而隨之，是以謂之「拘繫」也。上拘而系之，五乃從而維之。人之隨我，我不得已而受之，又從而維之以恩，結之以信，則其隨我也，綢繆固結而不可解，此周之王業所由興也。故王用享於西山。「兌」為西方，故有西山之象。西山，岐周也。太王避狄而去邠，邠人曰：「仁人也，不可失也。」從之者如歸市，不得已而邑於岐山之下居焉，是謂「拘繫之乃從維之」也。逮於文王，小心事紂，而海濱二老歸就其養，虞、芮二國來質厥成，其享不亦宜乎？詩云：「天作高山，太王荒之。彼作矣，文王康之。彼徂矣，岐有夷之行，子孫保之。」此之謂也。子曰：「拘繫之，上窮也。」窮上者必反下，是以上六之於九五，有「拘繫」之象也。其當殷之末世，周之盛德耶？序卦曰：「以喜隨人者必有事，故受之以蠱。蠱者，事也。」「蠱」之成卦，隨之反也。自「隨」之「蠱」，六爻盡變而成也。所以為「隨」者，剛來下柔也；及其為「蠱」，則剛上柔下矣。所以為「隨」者，動而說也；及其為「蠱」，則「巽」而止矣。雜卦曰：「隨，無故也。」序卦曰：「以喜隨人者必有事。」傳不云乎，「無故者，必有其故也。」聖人深究天下萬物之情狀，知其無故而「以喜隨人」，必將有事焉，是故受之以「蠱」也。老子曰：「將欲取之，必姑與之。」其「隨蠱」之序乎？子曰：蠱者，事也。揚雄作大玄，其準蠱也，以務與事。尚書大傳曰：乃命五史，以書五帝之蠱事。然則「蠱」之訓「事」，其來尚矣。春秋左氏：「趙孟問秦醫曰：何謂蠱？對曰：淫溺惑亂之所生也。於文，皿蟲為蠱，谷之飛亦為蠱。在易，女惑男，風落山，謂之蠱。」是以學者疑焉。為之說曰：「器久不用而蟲生之，謂之蠱；人久宴溺而疾生之，謂之蠱，天下久安無為而弊生之，謂之蠱。」夫蠱非事也，以天下為無事而不事事，則後將有不勝事矣。此蠱之所以為事也，是固然矣。然文王、孔子彖、象、序、雜，皆「元亨利涉」之辭，而不復言宴安湛溺之義。今將取正於秦醫之論「女惑男，風落山謂之蠱」，則於彖、象之情矛盾而不合。愚為更之曰：「蠱」之訓「事」，猶「亂」之訓「治」也。書盤庚曰：「亂越厥家。」梓材曰：「厥亂為民。」義皆訓「治」。不言「治」而言「亂」者，亂而治之，非守成之治也。今易之「蠱」，義皆訓「事」，不言「事」而言「蠱」者，蠱而有事，非循常之事也。是故「亂」既訓「治」，不復言「亂」；「蠱」既訓「事」，不復言「蠱」。系曰：「窮則變，變則通，通變之謂事。」此之謂也。故彖言「利涉」，象曰「育德振民」，序言「有事」，雜卦言「飭」。商之三宗，周之宣王，應其義矣。蠱：元亨，利涉大川，先甲三日，後甲三日。彖曰：「蠱，剛上而柔下，巽而止，蠱。蠱元亨」，而天下治也。「利涉大川」，往有事也。「先甲三日，後甲三日」，終則有始，天行也。下巽上艮成卦曰「蠱」者，初為巽，二為兌，三為震，四為艮。巽為風，震為雷，艮為山，兌為澤。風雷者，所以鼓舞萬物者也；而山澤者，所從受之者也，是以謂之蠱也。蠱以艮、巽成卦。巽，長女也；艮，少男也。男雖少而在上，女雖長而在下。六五、九二，艮、兌相交，而剛柔上下不失其正，是以謂之蠱也。巽，巽也；艮，止也。止而不巽，則無以順天下之情；巽而不止，則無以立天下之極。巽而止，所以為蠱也。故子曰：「剛上而柔下，巽而止，蠱。」「蠱，元亨，利涉大川。」何謂也？曰：蠱之四象，止以巽於隨，其為「元亨利貞」，宜與隨同，而象不言貞者，隨下震而上兌，震仲春而兌仲秋也，震旦而兌夕也。蠱下巽而上艮，巽在春夏之交，而艮在冬春之際，巽非日中而艮非夜半，故曰失貞之象，本職諸艮，蠱之上艮，宜系之貞矣，然而獨不言之，何也？蠱，事也；貞者，事之幹也，幹立而後枝葉有所遂。今以蠱為卦，而元亨與利兼之，雖不言「貞」，可以互見之矣。雖不言「貞」，而系之「先甲」「後甲」，則終始之義備矣。君子之立事也，智以謀之，信以守之，發而為仁，達而為禮，行而為義。有所不為，為之而無不成；有所不革，革之而無不就。故曰「蠱元亨而天下治也」。「利涉大川」，何謂也？曰：巽為木，兌為澤，震為足，艮為山，木浮於澤而足履于山，利涉之象也。方蠱之時，非垂拱無為而治者也，必有所涉而後濟焉。書曰：「若涉淵水，予惟往求朕攸濟」是也。若畏其難而憚其勞，則宴安苟且，終於委靡而已矣。故子曰：「利涉大川，往有事也」。「先甲三日，後甲三日」，何謂也？曰：甲者，震也。「蠱」之上九為震先甲也；九三為震，後甲也。蓋自大撓造甲子，起於五行，自甲至癸，為天一地十之數，自子至亥，為乾坤十二位之象。甲卯，東方木也，在易為「震」；庚酉，西方金也，在易為「兌」。聖人作易起於八卦，其見於爻象者，不言其卦而言其物。「蠱」之三，上有震體，不謂之震而謂之甲。「巽」之三，上有兌體，不謂之兌而謂之庚。先甲三日起於子而終於寅，後甲三日起於卯而終於巳。寅者，艮也。巳者，「巽」也。至是而一陰生矣。先庚三日起午而終於申，後庚三日起酉而終於亥。申者，坤也。亥者，乾也。陰極而陽生矣。聖人於此著消息之義焉。蠱之六爻，上為震，四為艮，先甲三日，起子而盡於寅也。三為震，初為巽，後甲三日，起卯而終於巳也。甲、卯、震同位而異名，初之於四，三之於上，其相去也，皆以三爻，是以系之三日也。故曰「先甲三日，後甲三日，終則有始，天行也」。聖人貴陽而賤陰，好治而惡亂。後甲在巽，一陰之候，聖人之所懼也。故因艮巽之中有重震之象，而著其義焉。天下之物，未有成而不壞者，天下之事，未有新而不敝者。陽於此終，陰於此始，天運之行，𫝑將至之。物極則反，道窮則變，變而通之，乃可以久，是則蠱「元亨利涉」之義也。若夫先庚後庚，其象為離。離者午也。陰起午而終亥，然後一陽生焉，故曰「無初有終」。所以然者，自蠱而巽變，六五一爻而成之，一爻之變，而先後有甲庚之異，言易者可以不求其故而狥其臆說也哉？或曰：「子以蠱之艮巽明後甲先甲之象，既有徵矣。先庚為坤，後庚為乾，而巽之六位，上下反覆，不見乾坤之象，何也？」曰：同歸而殊塗，一致而百慮。蠱之先甲「後甲，既取諸震，又取諸艮巽，而義既明矣。巽」之「先庚」「後庚」，既取諸「兌」，又取諸九五，五為「離」，先庚之所起也，其義不又明乎哉？「巽」之無乾坤，猶「蠱」之無「坎」也，而可以一義必之邪？使其爻象往復，無以相異，則既言於「蠱」，不必出之於「巽」矣。「蠱」以「艮巽」成卦，故著於象。「巽」以「離」象居五，故繫於爻。學者詳思焉，庶乎其得之矣。蘇氏曰：先甲三日，子、戌、申也。申盡於巳，而陽盈矣。盈將上陰，治將生亂，故授之以後甲。後甲三日，午、辰、寅也。寅盡於亥，然後陰極而陽生。「蠱」九五以幹之，故其治亂皆極其自然之勢。勢窮而後變，故曰：「終則有始，天行也。若夫先庚三日，午、辰、寅也。後庚三日，子、戌、申也。庚之所後，甲之所先也。先庚盡於亥，後庚盡於己，先陰而後陽，先亂而後治，故曰：無初有終」。又曰：「不言於象而言於五者，明此九五之功，非巽之功也」。其說雖晦，而理亦深然若如深諭，當言「先甲三旬」，不當言「三日」也。且於「蠱」之四象無所發明，故存而不取。象曰：山下有風，「蠱」。君子以振民育德。「山」者，「艮」也。「風」者，「巽」也。風行山下，有振動生育之象。不動則不生，不振則不育，故君子體之，以振民而育德焉。振民則取諸風，育德則取諸山也。孔子曰：「君子之德風，小人之德草。草上之風，必偃。」孟子曰：「匡之直之，輔之翼之，使自得之，又從而振德之。」此之謂也。而秦醫之論，以為女惑男，風落山，謂之蠱。夫搖落之風，曷為行於山下？媚惑之女，曷為長於少男？吾不知其說也。學者信傳而疑經，豈不過甚矣哉？雜卦曰：「蠱則飭也。」飭，治也，謹也。剛上而柔下，蠱之所以為飭也。剛上而柔下，君臣、父子、夫婦皆然矣。蠱之為事，非循常之事也，有自下飭上之義焉。施之君臣之間，夫婦之際，義或未安，故直以父子明之。「蠱」之諸爻，上下反覆，皆震、巽、艮、兌之象。震，長男也；巽，長女之任也。少男二女，非其任矣，故但以先甲。巽，長女也。艮，少男也。兌，少女也。父在而幹其蠱者，後甲明其義焉。甲者，震也。先後者，以上下言之也。上震三爻，父也；下震三爻，子也。子雖幹蠱，不先於父，此蠱之所以為飭也。諸家舊說，皆隨爻取義，不以相應求之。蓋見六四言「裕父之蠱」，六五言「幹父之蠱」，二爻在上故也。此所謂以文害辭，以辭害意也。其在他卦，初九相應之義者，見其爻辭，疑若相應，又從而牽合之，以此求易，宜其不通也。愚豈好辨哉？誠不得已也。如諸家之論，九二「幹母之蠱」，六四「裕父之蠱」，猶稍異於諸爻，乃若「幹父之蠱」，二爻同稱，何以別其優劣乎？初六曰：「幹父之蠱，有子，考旡咎，厲終吉。」而象曰：「意承考也。」六五曰：「幹父之蠱，用譽。」而象曰：「承以德也。」二爻不同，其義安在？九三又曰：「幹父之蠱，小有悔，無大咎。」而象曰：「終無咎也。」夫易之為書，所以教人君國齊家，而示之以吉凶悔吝者也。為人子而幹父之蠱，當用柔乎？抑用剛乎？苟剛柔雜用而無所適從，是聖人之惑之也。此乃經之過也。其失在於不按卦以求義，而執文以害辭也。譬如入人之室，一父而五子，則父為家主，子皆從父者也；一母而五子，則母為家主，子皆從母者也。若兄弟同居，則其妻妾若子各從其主者也。是故卦有五陽而一陰、五陰而一陽者；有二陽而四陰、二陰而四陽者，陰陽各居其半者，各以其類別之也。其或應或不應者，則又隨其卦義而辨之也。隨之諸爻，以男女長少為義，或以遠而相應，或以近而相隨，或以上而隨下，或以陽而隨陰。而「蠱」之諸爻，以父子為義，上三爻為父，下三爻為子。視其應與不應，而吉㓙悔吝可見矣。故曰：「隨無故也，蠱則飭也。」不既明甚矣乎？初六：幹父之蠱，有子，考無咎，厲終吉。象曰：「幹父之蠱」，意承考也。初六，「巽」也，以陰居剛而在下卦之下，其應六四，四以陰居柔而體乎「艮巽」，故曰：「幹父之蠱」。「巽」，長女也；「艮」，少男也。「艮」「巽」同居，莫能有制，「蠱」之所以為「蠱」也。四之象道可謂不振矣。初雖居剛，有幹蠱之才，而四以陰柔，志不相應，「巽」以承父，不失其為子之道矣。有子之賢，雖僨必起，故曰：「有子，考無咎。」生謂之「父」，歿謂之「考」。「有子」者，有其才而未用也。當父之時，初雖幹蠱而勢未得行，見志不從，又敬不違，四之不振，猶自若也，安能免於咎乎？父歿而子克家，則為「無咎」矣。故曰：「厲終吉」。父「巽」乎上，子「巽」乎下，家道不振，亦已危矣。有子克家，故「終吉」也。子曰：「幹父之蠱，意承考也。」論語曰：「父在，觀其志，父沒觀其行。」其此之謂歟！九二：幹母之蠱，不可貞。象曰：「幹母之蠱」，得中道也。九二，「兌」也，以陽居柔而在下卦之中，應乎六五之陰，故曰：「幹母之蠱」。「艮」為少男，「兌」為少女，有感應相與之義焉。二以陽居柔，而五以陰居剛，不約而孚矣。夫母從子者也，子從母者也。母柔而子剛，於義為得矣。然而不可以為貞也，有母在上，而專以剛行之，有時而違咈矣。唯九三居柔體說，履得其中，孝以事親，義以幹蠱，剛柔適中，子道盡矣。故子曰：「幹母之蠱，得中道也。」九三：幹父之蠱，小有悔，無大咎。象曰：「幹父之蠱」，終無咎也。九三上體為「震」，下體為「兌」，以陽居剛而在下之上，其上九，上亦「震」也，上震下「巽」，所謂「先甲後甲」者也。二爻俱陽，若不相應，乃傳家而主器者也。故曰：「幹父之蠱。」上九，賢父也；九三，賢子也，皆陽剛而體「震」故也。三爻體「兌」，說以從父也。上九知其子之賢，而釋其器之重，自處於優遊無事之域，而以幹蠱之任委之。三受任於父，得以事行無所顧忌，則其不應焉者，乃所以為任之專也。家事大小，不必諮而後行也。故曰：「小有悔，無大咎。」父在而子專行，雖父之命，然內外之事、上下之情，其能無小悔乎？上九之賢，既已知其子而任之矣。三之所為，皆幹父之蠱，而非狥其私者也，是以雖「小悔」而「無大咎」也。故子曰：「幹父之蠱，終無咎也。」或曰：子以「巽」「艮」同居，為四之不振，三亦「震」「兌」同居也，烏在其為賢子乎？曰：女長而男少，則男聽於女；男長而女少，則女聽於男。三以陽居剛，而四以陰居柔，不可以同年而語之矣。六四：裕父之蠱，往見吝。象曰：「裕父之蠱」，往未得也。六四上體為艮，下體為「巽」，以陰居柔而在上卦之下，下應初六，二爻俱陰，無相得之義，故曰：「裕父之蠱」。「裕」，益也。傳曰：「以水濟水，以火濟火，名之曰益」，多裕蠱之謂也。「巽」為長女，「艮」為少男。長女少男，莫適為正，不可以為幹蠱之子，益父之事而已。故曰：「往見吝」。初六幹蠱之子欲往而飭之，父為之主，不應於己，宜其「見吝」也。或曰：初、四皆巽也，一為男，一為女；一為賢，一為不肖，何也？曰：下三爻為子，皆有「巽」「兌」之象，為女，無干蠱之義，則「巽」「兌」者，上之所以事親。上三爻為父，而「艮」「巽」居焉，則是長女少男相與陷父於不義者也。初以「巽」居剛，而四「巽」以居柔，牝牡賢愚，於此可見矣。故子曰：「裕父之蠱，往未得也。」其在初六曰：「意承考也。」所以互明之歟？六五：幹父之蠱，用譽。象曰：「幹父用譽」，承以德也。六五，「艮」也，以陰居剛而在上卦之中，應乎九三之「兌」，故曰：「幹父之蠱」。「艮」，止也；「兌」，說也。六五，賢母也；九二，賢子也。婦人旡家，以夫為家。母雖在上，而所幹者父之事也。不曰「夫」而曰「父」者，從子而言也。六五為母，則九三幹母之事者也，故曰：「用譽」。母以柔幹乎上，子以剛乾乎下，上下相應，內外相與，德盛而教尊，家肥而譽顯，不亦宜乎？故子曰：「幹父用譽，承以德也。」或曰：六五為母，而「艮」居之，不亦裕蠱之象乎？曰：少男者，母之所保抱攜持者也。以六居五，應乎九二，無「裕蠱」之嫌矣。上九：不事王侯，高尚其事。象曰：「不事王侯」，志可則也。上九，「震」也。以陽居柔，而在上卦之上，其應九三，「震」、「兌」也。二「震」重剛，無相與之義，故曰「不事王侯」。王者，五也；「侯」者，二也。在五之上而不應五，「不事王侯」之象也。夫「蠱」者，事也；「震」者，動也。當「蠱」之事而體乎「震」，宜若有為者矣。然而「蠱」之終也，終則變矣。九三之「震」既已能任其事，上九超然遠舉，不累於物，脫於是非利害之塗，而出乎塵垢粃糠之外，是乃「不事王侯」者也。「不事王侯」何義也？大夫七十而致政，老而傳家者也，故曰「高尚其事」。上九之「不事」，非不能事事也，年高而德卲，其所事者皆高尚於世俗而不屑為其細也。是以外致其位，內得其家，優遊無為，委任賢子，享「期頤」之壽，得「令終」之名也。人之所貴乎有子孫者，為其死而有所託，老而有所傳耳。昧者乃以「不事王侯」為君子之高節，然則周公之勤勞，仲尼之歷聘，皆失節而不正者也。聖人吉凶與民同志，而乃以「不事」為高，豈不小哉？治則見，亂則隱，方元亨利涉之時，非儉德避難之日，「不事王侯」，其義安在？故曰：「大夫七十而致政，老而傳家者也。」壯而能事，老而能傳，知足不辱，知止不殆，故子曰：「不事王侯，志可則也。」易有君臣、父子、夫婦之道焉，尊卑奠位，則三者同其義也。陰陽相求，必著夫婦之義；遠近鹹應，多取君臣之教。若夫蠱者，父子之義也，施之於君臣則悖矣。故初六有志而不敢往，九二「剛中」而不可貞，子道也，非臣道也。九三子得專行，「有悔」而無咎，子道也，亦非臣道也。人君雖高拱旡為，委任臣下，終不能如上九之不事事也。故爻皆以父子明之，而六五有「幹父用譽」之辭，上九有「不事王侯」之義。以國言之，則五為王而二為侯；以家言之，則五為妻而三為子。易之取義，不一而足，皆如是矣。禮曰：「事君有犯而無隱，事親有隱而無犯。」同歸或殊塗也。禪位之帝，繼體之君，可則以觀於蠱矣。周易經傳集解卷九。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
